    id: "montenegro-sastavci-bridge-landmarks-v2", "sights": {"de": [{"name": "Plaža Sastavci", "text": "Die Plaža Sastavci befindet sich direkt an der gleichnamigen Brücke und bietet eine urbane Oase für Erholungssuchende. Hier treffen sich Einheimische gerne auf ein erfrischendes Bad oder ein gemütliches Picknick am Ufer. Ein reizvoller Ort, um nach einem ausgiebigen Stadtspaziergang die Beine im kühlen Nass baumeln zu lassen.", "category": "recreational", "coords": [19.258227, 42.439518]}], "hu": [{"name": "Plaža Sastavci", "text": "A Plaža Sastavci közvetlenül az azonos nevű híd mellett található, és városi oázist kínál a kikapcsolódni vágyóknak. A helyiek szívesen találkoznak itt egy frissítő fürdőzésre vagy egy hangulatos piknikre a parton. Elbűvölő hely arra, hogy egy kiadós városi séta után belelógassa a lábát a hűsítő vízbe.", "category": "recreational", "coords": [19.258227, 42.439518]}], "ro": [{"name": "Plaža Sastavci", "text": "Plaža Sastavci este situată chiar lângă podul cu același nume și oferă o oază urbană pentru cei care caută recreere. Localnicilor le place să se întâlnească aici pentru o baie răcoritoare sau un picnic confortabil pe mal. Un loc încântător pentru a vă lăsa picioarele în apa rece după o plimbare lungă prin oraș.", "category": "recreational", "coords": [19.258227, 42.439518]}], "en": [{"name": "Plaža Sastavci", "text": "Plaža Sastavci is located right by the bridge of the same name and offers an urban oasis for those seeking recreation. Locals like to meet here for a refreshing swim or a cozy picnic on the shore. A delightful spot to dangle your legs in the cool water after an extensive city walk.", "category": "recreational", "coords": [19.258227, 42.439518]}]},
