    id: "montenegro-nikola-church-landmarks-v2", "sights": {"de": [{"name": "Kotorska plaža", "text": "Nur wenige Schritte von der Nikolauskirche entfernt, lädt die Kotorska plaža zu einer entspannten Pause am Rande der Bucht von Kotor. Reisende können hier das faszinierende Bergpanorama bewundern, während sie im ruhigen Wasser schwimmen. An warmen Sommertagen ist dieser zentrale Stadtstrand eine willkommene Erfrischung.", "category": "recreational", "coords": [18.768063, 42.429662]}], "hu": [{"name": "Kotorska plaža", "text": "A Szent Miklós-templomtól mindössze néhány lépésre található Kotorska plaža pihentető szünetre hív a Kotori-öböl partján. Az utazók itt a nyugodt vízben úszva csodálhatják meg a lenyűgöző hegyi panorámát. A meleg nyári napokon ez a központi fekvésű városi strand szívesen látott felfrissülést nyújt.", "category": "recreational", "coords": [18.768063, 42.429662]}], "ro": [{"name": "Kotorska plaža", "text": "La doar câțiva pași de Biserica Sf. Nicolae, Kotorska plaža vă invită la o pauză de relaxare pe marginea Golfului Kotor. Călătorii pot admira aici fascinanta panoramă montană în timp ce înoată în apa calmă. În zilele calde de vară, această plajă centrală a orașului este o răcorire binevenită.", "category": "recreational", "coords": [18.768063, 42.429662]}], "en": [{"name": "Kotorska plaža", "text": "Just a few steps away from St. Nicholas Church, Kotorska plaža invites you for a relaxing break on the edge of the Bay of Kotor. Travelers can admire the fascinating mountain panorama here while swimming in the calm water. On warm summer days, this central city beach is a welcome refreshment.", "category": "recreational", "coords": [18.768063, 42.429662]}]},
