    imageHint: "Kastio fortress Petrovac island",
    descriptionAdvanced: {
      de: "Die Festung Kastio, am Rande der Küstenstadt Petrovac gelegen, ist ein bedeutendes venezianisches Denkmal aus dem 16. Jahrhundert. Sie wurde ursprünglich errichtet, um die Küste vor Piratenüberfällen zu schützen und diente als strategischer Beobachtungsposten für die Republik Venedig. Das Bauwerk ist auf einer felsigen Halbinsel platziert, die den Hafen von Petrovac dominiert, und bietet einen beeindruckenden Blick auf die Inseln Katič und Sveta Nedelja. In der Nähe der Festung befand sich einst ein römisches Mosaik, was auf eine noch ältere Besiedlung des Ortes hindeutet. Im Laufe der Jahrhunderte wurde die Festung für verschiedene Zwecke genutzt, darunter als Quarantänestation und Militärposten. Heute ist Kastio ein beliebtes Touristenziel und beherbergt ein kleines Museum sowie eine Bar, die besonders bei Sonnenuntergang besucht wird. Die gut erhaltenen Mauern und die Kanonen aus dem 19. Jahrhundert verleihen dem Ort einen historischen Charme.",
      hu: "A Petrovac tengerparti városának szélén található Kastio-erőd a 16. századi velencei építészet egyik fontos emléke Montenegróban. Az erődöt eredetileg a kalóztámadások elleni védekezés céljából építették, és a Velencei Köztársaság fontos megfigyelőpontjaként szolgált a tengerparton. Az építmény egy sziklás félszigeten helyezkedik el, amely uralja Petrovac kikötőjét, és csodálatos kilátást nyújt a közeli Katič és Sveta Nedelja szigetekre. Az erőd közelében római kori mozaikokat is találtak, ami azt bizonyítja, hogy a terület már az ókorban is lakott volt. Az évszázadok során az erődöt különböző célokra használták, többek között karanténállomásként és katonai őrhelyként is működött. Ma Kastio népszerű turisztikai látványosság, ahol egy kis múzeum és egy hangulatos bár várja a látogatókat, különösen naplemente idején. A jól megőrzött falak és a 19. századi ágyúk különleges történelmi hangulatot árasztanak.",
      ro: "Cetatea Kastio, situată la marginea orașului de coastă Petrovac, este un monument venețian semnificativ care datează din secolul al XVI-lea. A fost ridicată inițial pentru a proteja coasta de raidurile piraților și a servit ca punct strategic de observație pentru Republica Veneția în această parte a Adriaticii. Fortăreața este amplasată pe o peninsulă stâncoasă ce domină portul Petrovac, oferind o priveliște impresionantă asupra insulelor Katič și Sveta Nedelja. În apropierea cetății au fost descoperite mozaicuri romane, ceea ce indică o locuire mult mai veche a acestui sit strategic. De-a lungul secolelor, fortificația a avut diverse utilizări, funcționând inclusiv ca stație de carantină și post militar. Astăzi, Kastio este o destinație turistică populară, găzduind un mic muzeu și un bar care devine punctul central al orașului la apus. Zidurile bine conservate și tunurile din secolul al XIX-lea oferă vizitatorilor o incursiune autentică în istoria maritimă a regiunii.",
      en: "Kastio Fortress, located at the edge of the coastal town of Petrovac, is a significant 16th-century Venetian monument. It was originally built to protect the coastline from pirate raids and served as a strategic lookout point for the Republic of Venice in the southern Adriatic. The fortress is perched on a rocky peninsula that overlooks Petrovac's harbor, offering stunning views of the nearby Katič and Sveta Nedelja islets. Roman mosaics discovered nearby suggest that the area has been inhabited since antiquity, long before the Venetian walls were raised. Over the centuries, the fortification has served various roles, including a quarantine station and a military outpost. Today, Kastio is a beloved tourist landmark, featuring a small museum and a terrace bar that is particularly popular at sunset. The well-preserved ramparts and 19th-century cannons provide a historic charm that defines the town's seaside silhouette.",
      es: "La fortaleza veneciana Kastio, del siglo XVI, protegía el puerto de Petrovac de los ataques piratas y sirvió más tarde como lazareto para marineros enfermos de la región.",
      pt: "A fortaleza veneziana Kastio, do século XVI, protegia o porto de Petrovac de ataques de piratas e serviu mais tarde como lazareto para marinheiros doentes da região.",
      fr: "La forteresse vénitienne Kastio du XVIe siècle protégeait le port de Petrovac des attaques de pirates et a servi plus tard de lazaret pour les marins malades de la région.",
    },
    factsAdvanced: {
      de: ["Erbaut im 16. Jahrhundert durch die Republik Venedig.", "Diente ursprünglich zum Schutz vor Piratenangriffen.", "Befindet sich auf einer markanten Klippe über dem Hafen.", "Beherbergt Kanonen aus der Zeit der österreichischen Herrschaft.", "In der Nähe wurden römische Mosaike aus dem 3. Jh. n. Chr. gefunden.", "Wurde im 19. Jahrhundert als Quarantänestation genutzt."],
      hu: ["A Velencei Köztársaság építette a 16. században.", "Eredeti funkciója a kalózok elleni védelem volt.", "Egy látványos sziklán fekszik közvetlenül a kikötő felett.", "Az osztrák uralom idejéből származó ágyúk láthatók rajta.", "A közelében 3. századi római mozaikokat tártak fel.", "A 19. században karanténként is funkcionált a tengerészek számára."],
      ro: ["Construită în secolul al XVI-lea de către Republica Veneția.", "Rol inițial de apărare împotriva atacurilor piraților.", "Amplasată pe o stâncă abruptă deasupra portului local.", "Adăpostește tunuri care datează din perioada austriacă.", "În proximitate s-au descoperit mozaicuri romane din secolul III d.Hr.", "A fost utilizată ca stație de carantină în secolul al XIX-lea."],
      en: ["Built in the 16th century by the Republic of Venice.", "Originally designed to defend against pirate incursions.", "Situated on a prominent cliff overlooking the town harbor.", "Features cannons dating from the period of Austrian rule.", "Roman mosaics from the 3rd century AD were found nearby.", "Served as a quarantine station during the 19th century."],
      es: ["Construida en el siglo XVI", "Sirvió como almacén aduanero veneciano", "Incluye un lapidario con piezas expuestas", "Situada directamente en el borde norte del puerto", "Nombre anterior: Castel Lastva", "Se encontraron cañones de la Edad del Bronce"],
      pt: ["Construída no século século XVI", "Serviu como entreposto aduaneiro veneziano", "Inclui um lapidário com exposições", "Localizada diretamente na margem norte do porto", "Nome anterior: Castel Lastva", "Canhões da Idade do Bronze foram encontrados"],
      fr: ["Construite au XVIe siècle", "Servait d'entrepôt douanier vénitien", "Comprend un lapidaire avec des objets exposés", "Située directement au bord nord du port", "Ancien nom : Castel Lastva", "Canons de l'âge du bronze trouvés"],
    },
