      ro: ["Fondat în 1926 în inima capitalei istorice Cetinje.", "Sediul central se află în Vladin Dom, edificiu neobaroc din 1910.", "Deține prețioasa icoană a Fecioarei Maria din Philermos.", "Expune Octoihul din 1494, prima carte tipărită a slavilor de sud.", "Cuprinde patru muzee tematice: istorie, artă, etnografie și regalitate.", "Acoperă istoria Muntenegrului din antichitate până în 1945."],
