      es: ["Año de fundación: 1896", "Número de objetos: más de 100.000", "Superficie del museo: 5000 m²", "Número de departamentos: 3", "Altura del palacio: 15 m", "Visitantes por año: aprox. 50.000"],
      pt: ["Ano de fundação: 1896", "Número de objetos: mais de 100.000", "Área do museu: 5000 m²", "Número de departamentos: 3", "Altura do palácio: 15 m", "Visitantes por ano: cerca de 50.000"],
      fr: ["Année de fondation : 1896", "Nombre d'objets : plus de 100 000", "Surface du musée : 5000 m²", "Nombre de départements : 3", "Hauteur du palais : 15 m", "Visiteurs par an : environ 50 000"],
