      pt: ["Consagrada no ano 1166", "Centro da diocese de Kotor", "Pérola arquitetónica românica", "Renovada várias vezes"],
      fr: ["Consacrée en 1166", "Centre du diocèse de Kotor", "Perle architecturale romane", "Rénovée plusieurs fois"],
