      en: ["Built in the 17th century", "City center", "Historical meeting place", "Landmark"],
      es: ["Construida en el siglo XVII", "Centro de la ciudad", "Punto de encuentro histórico", "Emblema"],
      pt: ["Construída no século XVII", "Centro da cidade", "Ponto de encontro histórico", "Marco histórico"],
