    imageHint: "Clock tower Herceg Novi",
    descriptionAdvanced: {
      de: "Der Uhrturm von Herceg Novi, bekannt als Sat Kula, ist das markanteste Symbol der Stadt und trennt die Unterstadt von der Oberstadt. Er wurde im Jahr 1667 während der osmanischen Herrschaft im Auftrag von Sultan Mahmud errichtet und diente ursprünglich als zeremonielles Stadttor. Die Architektur verbindet orientalische Elemente mit den später hinzugefügten Einflüssen der westlichen Befestigungskunst. Der Turm beherbergt eine Glocke, die noch heute die Zeit schlägt, und eine Uhr, die über Jahrhunderte ein wichtiger Orientierungspunkt für Händler und Seefahrer war. Im Inneren des Durchgangs befindet sich eine Skulptur der 'Schwarzen Madonna', die aus verkohltem Holz geschnitzt wurde und eine tiefe religiöse Bedeutung für die Anwohner besitzt. Der Aufstieg zum Turm bietet einen weiten Blick über die Dächer der Altstadt bis hin zum Eingang der Bucht von Kotor. Als eines der wenigen erhaltenen Denkmäler aus der Türkenzeit ist der Sat Kula ein unverzichtbarer Teil des kulturellen Erbes von Herceg Novi.",
      hu: "A herceg novi Óratorony (Sat Kula) a város legfontosabb jelképe, amely az óváros alsó és felső részét köti össze. Az építményt 1667-ben emelték az oszmán hódoltság idején, eredetileg a város főkapujaként és őrtornyaként funkcionált. Építészeti megjelenése az évszázadok során változott, de megőrizte masszív, erőd jellegét és a keleties stílusjegyeket. A torony alatt található átjáró falán látható a 'Fekete Madonna' (Crna Bogorodica) szobra, amelyet egy elszenesedett fadarabból faragtak, és a helyiek körében nagy tisztelet övezi. Az óra mechanizmusa hosszú ideig a város lüktetését szabályozta, és ma is működőképes állapotban van. A toronyból nyíló kilátás az egész Kotori-öböl bejáratát és a várat is magába foglalja, vonzva a látogatókat a világ minden tájáról. Történelmi jelentőségét növeli, hogy túlélte a térséget sújtó nagyobb földrengéseket és ostromokat is.",
      ro: "Turnul cu Ceas din Herceg Novi, cunoscut sub numele de Sat Kula, este cel mai recognoscibil reper al orașului, marcând intrarea în centrul vechi. Acesta a fost construit în anul 1667, în perioada dominației otomane, sub îndrumarea lui Mustafa Pașa. Structura a servit inițial drept poartă principală de acces și punct strategic de observație pentru apărarea cetății. Turnul îmbină elemente de arhitectură islamică cu modificări ulterioare aduse în perioadele venețiană și austriacă. În interiorul arcadei sale de la bază se află o sculptură rară din lemn ars, cunoscută sub numele de 'Madona Neagră', considerată o relicvă protectoare a orașului. Ceasul din vârful turnului a fost timp de secole instrumentul principal de măsurare a timpului pentru negustorii locali. Astăzi, Sat Kula este punctul central al vieții sociale din Herceg Novi, fiind situat în piața principală, unde se desfășoară numeroase evenimente culturale.",
      en: "The Clock Tower in Herceg Novi, locally known as Sat Kula, is the definitive symbol of the town, acting as a gateway between the lower and upper parts of the historic center. It was built in 1667 during the Ottoman rule by order of Sultan Mahmud to serve as the main ceremonial entrance to the fortified city. The tower's architecture is a blend of oriental styles with structural reinforcements added during subsequent Venetian and Austrian periods. Inside the tower's arched passage, there is a unique wooden sculpture of the 'Black Madonna,' carved from charred wood, which holds significant religious and historical value for the townspeople. The clock mechanism itself has been replaced several times over the centuries, but the tower has maintained its role as the town's primary timekeeper. Standing tall above the main square, it offers visitors a picturesque view of the old stone houses and the distant Adriatic Sea. Sat Kula remains a preserved piece of 17-century history, surviving major earthquakes and representing the diverse cultural layers of Herceg Novi.",
      es: "La Torre del Reloj de Herceg Novi, conocida como Sahat Kula, fue construida en el siglo XIX y es un emblema del casco antiguo. La torre tiene 18 metros de altura y cuenta con un reloj de cuatro esferas. Se alza en la plaza principal y servía como punto de encuentro. La torre fue restaurada tras un terremoto en 1979. El entorno está caracterizado por calles estrechas y arquitectura mediterránea. La Torre del Reloj es un símbolo de la historia otomana y veneciana de la ciudad.",
      pt: "A Torre do Relógio de Herceg Novi, conhecida como Sahat Kula, foi construída no século XIX e é um marco da cidade velha. A torre tem 18 metros de altura e possui um relógio com quatro mostradores. Situa-se na praça principal e servia como ponto de encontro. A torre foi restaurada após um sismo em 1979. Os arredores são caracterizados por ruelas estreitas e arquitetura mediterrânica. A Torre do Relógio é um símbolo da história otomana e veneziana da cidade.",
      fr: "La tour de l'horloge d'Herceg Novi, connue sous le nom de Sahat Kula, a été construite au XIXe siècle et est un emblème de la vieille ville. La tour mesure 18 mètres de haut et possède une horloge à quatre cadrans. Elle se dresse sur la place principale et servait de point de rencontre. La tour a été restaurée après un tremblement de terre en 1979. Les environs sont marqués par des ruelles étroites et une architecture méditerranéenne. La tour de l'horloge est un symbole de l'histoire ottomane et vénitienne de la ville.",
    },
    factsAdvanced: {
      de: ["Der Turm wurde im Jahr 1667 auf Befehl von Sultan Mahmud erbaut.", "Er diente ursprünglich als Haupttor zur befestigten osmanischen Stadt.", "Die berühmte 'Schwarze Madonna' im Durchgang wurde aus verbranntem Holz gefertigt.", "Der Turm ist etwa 16 Meter hoch und dominiert den Hauptplatz der Altstadt.", "Die heutige Uhr wurde erst im 19. Jahrhundert installiert.", "Er ist einer der wenigen erhaltenen Uhrtürme aus der osmanischen Zeit in Montenegro."],
      hu: ["Az óratornyot 1667-ben, az oszmán uralom idején építették.", "Eredeti funkciója a város belső várfalának főbejárata volt.", "A torony átjárójában látható 'Fekete Madonna' szobra a város egyik legfontosabb ereklyéje.", "A Sat Kula név török eredetű, jelentése egyszerűen 'óratorony'.", "Az építmény magassága és elhelyezkedése miatt kiváló kilátópont.", "A torony falaiba több korábbi korszakból származó kőfaragványt is beépítettek."],
      ro: ["Turnul a fost ridicat în 1667, fiind o donație a sultanului Mahmud.", "A reprezentat poarta principală de vest a orașului medieval Herceg Novi.", "Relieful 'Madona Neagră' din interior a fost realizat dintr-un trunchi de copac ars.", "Mecanismul actual al ceasului a fost adus din Franța în secolul al XIX-lea.", "Sat Kula este situat în Piața Nikola Đurković, cel mai animat loc al orașului.", "Structura a fost consolidată major după cutremurul catastrofal din 1979."],
      en: ["Built in 1667 during the reign of Sultan Mahmud of the Ottoman Empire.", "The tower functioned as the primary ceremonial gateway to the upper town.", "The 'Black Madonna' sculpture inside was carved from a piece of charred wood.", "It stands as a 16-meter tall stone structure in the heart of the Old Town.", "The clock face visible today dates back to the 19th-century renovations.", "The name 'Sat Kula' is derived from Turkish, meaning 'Clock Tower'."],
      es: ["Altura: 18 metros", "Construida en el siglo XIX", "Cuatro esferas de reloj", "Restaurada tras 1979", "Ubicación: Plaza principal del casco antiguo", "De piedra y ladrillo"],
      pt: ["Altura: 18 metros", "Construída no século XIX", "Quatro mostradores", "Restaurada após 1979", "Localização: Praça principal da cidade velha", "De pedra e tijolo"],
      fr: ["Hauteur : 18 mètres", "Construite au XIXe siècle", "Quatre cadrans", "Restaurée après 1979", "Emplacement : Place principale de la vieille ville", "En pierre et brique"],
    },
